export const query="\n    query CruiseSearch($filters: String, $sort: CruiseSearchSort, $pagination: CruiseSearchPagination) {\n      cruiseSearch(filters: $filters, sort: $sort, pagination: $pagination) {\n        results {\n          total\n          cruises {\n            masterSailing {\n              itinerary {\n                code\n                name\n                media {\n                  images {\n                    path\n                  }\n                }\n                totalNights\n                departurePort {\n                  name\n                }\n                ship {\n                  code\n                  name\n                }\n                days {\n                  number\n                  ports {\n                    activity\n                    port {\n                      code\n                      name\n                      media { images { path } }\n                    }\n                  }\n                }\n              }\n            }\n            sailings {\n              id\n              sailDate\n              startDate\n              productViewLink\n              bookingLink\n              lowestStateroomClassPrice {\n                price {\n                  currency {\n                    code\n                    symbol\n                  }\n                  value\n                }\n              }\n              taxesAndFees {\n                value\n              }\n              taxesAndFeesIncluded\n            }\n          }\n        }\n      }\n    }";
